export const isRuleName = (name: string): boolean => {

	return defined(name.match(/^[A-Za-z$_][A-Za-z0-9$_-]*$/))
}

// ---------------------------------------------------------------------------

export class CRule {
	private name: string
	private pattern: string = ''
	private lCode: string[] = []

	constructor(name1: string) {
		this.name = name1;
		assert(isRuleName(this.name), `Bad name: <${this.name}>`)
	}

	getName(): string {
		return this.name
	}

	getPattern(): string {
		return this.pattern
	}

	setPattern(pat: string): void {
		this.pattern = pat
		return
	}

	addCode(line: string): void {
		const lMatches = line.match(/^(\s*)return\s+(.*);$/)
		if (defined(lMatches)) {
			const [_, prefix, valueStr] = lMatches
			this.lCode.push((prefix + 'return' + ' pm.result(' + valueStr + ');'))
		}
		else {
			this.lCode.push(line)
		}
		return
	}

	patternStr(): string {
		const hashPos = this.pattern.indexOf('#')
		if (hashPos === -1) {
			return indented(this.pattern) + ' ->'
		}
		else {
			return indented(this.pattern.replace('#', '-> #'))
		}
	}

	numCodeLines(): number {
		return this.lCode.length
	}

	codeBlock(type: THeraType): string[] {
		return indented(this.lCode, 2)
	}

	toString(type: THeraType): string {
		return [
			this.name,
			this.patternStr(),
			indented(mkCodeBlock(this.lCode, type), 2),
			'\n'
			].join('\n')
	}
}

// ---------------------------------------------------------------------------

const buildHeraFile = (
		lMainCode: string[],
		lResetCode: string[],
		lRules: CRule[],
		type: THeraType,
		debug: boolean = false
		) => {

	const mainCode = mkCodeBlock(lMainCode, type)
	if (debug) {
		DUMP(mainCode, 'mainCode')
	}

	const resetCode = mkCodeBlock(lResetCode, type)
	if (debug) {
		DUMP(resetCode, 'resetCode')
	}

	const lRuleBlocks = lRules.map((rule) => rule.toString(type))
	if (debug) {
		let i1 = 0;for (const block of lRuleBlocks) {const i = i1++;
			DUMP(block, `Rule[${i}]`)
		}
	}

	let lParts: string[] = []
	lParts.push(
		"```",
		"import {CParseMatches} from 'parse-utils';",
		"export let pm = new CParseMatches();",
		"")
	if (nonEmpty(mainCode)) {
		lParts.push(mainCode, "")
	}

	lParts.push(
		"export const reset = (text: string): void => {",
		indented("pm.reset(text);"),
		indented(resetCode),
		indented('}'),
		"```",
		'',
		...lRuleBlocks)
	const result = lParts.join('\n').replaceAll('\t', spaces(2))
	if (debug) {
		DUMP(result, 'Result')
	}
	return result
}

// ---------------------------------------------------------------------------

export const decom = (line: string): string => {

	return line.replace(/^(\s*)#(\s)/, "$1//$2")
}

