export const preprocessHera = (
		iter: string | TIterator<string>,
		type: THeraType = 'typescript',
		debug: boolean = false
		): string => {

	if (isString(iter)) {
		iter = allLinesInBlock(iter)
	}
	resetOneIndent()

	const lMainCode: string[]  = []
	const lResetCode: string[] = []

	let curRule: CRule = new CRule('Dummy')
	let lRules: CRule[] = []

	const result = fromFSM(iter, [

		// 0 --- start
		(line: string): TState => {
			if (line === '#reset') {
				return 1
			}
			else {
				lMainCode.push(decom(line))
				return 0
			}
		},

		// 1 --- in reset function
		(line: string): TState => {
			if (isEmpty(line)) {
				lResetCode.push('')
				return 1
			}
			else {
				const [level, str] = splitLine(line)
				if (level === 0) {
					curRule = new CRule(line)
					return 2
				}
				else {
					lResetCode.push(undented(decom(line)))
					return 1
				}
			}
		},

		// 2 --- have rule name, want pattern
		(line: string, i: number): TState => {
			if (isEmpty(line)) {
				return 2
			}
			else {
				const [level, str] = splitLine(line)
				assert((level === 1),
					`Expecting pattern for rule ${curRule.getName()} on line ${i}`)
				curRule.setPattern(str)
				curRule.addCode(`pm.match('${curRule.getName()}', $loc);`)
				return 3
			}
		},

		// 3 --- have pattern, want code
		(line: string, i: number): TState => {
			if (isEmpty(line)) {
				return 3
			}
			else {
				const [level, str] = splitLine(line)
				if (level === 0) {
					lRules.push(curRule)

					// --- create a new rule
					curRule = new CRule(line)
					return 2
				}
				else if (level === 1) {
					const ruleName = curRule.getName()
					croak(`Unexpected pattern for rule ${ruleName} on line ${i}`)
				}
				else {
					// --- first line of code must be at level 2
					if (curRule.numCodeLines() === 0) {
						assert((level === 2), "First line of code must be level 2")
					}
					curRule.addCode(indented(decom(str), level-2))
					return 3
				}
			}
		}
		], (state: TState): void => {
			if (state === 3) {
				lRules.push(curRule)
				const str = buildHeraFile(lMainCode, lResetCode, lRules, type, debug)
				throw str
			}
			else {
				croak(`Ended in state ${state}`)
			}
	})
	assert((typeof result === 'string'), "result not a string")
	return result
}

